"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["7800"],{44202(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.grupo_formulario.campo_com_impedimento","status":422,"titulo":"O campo do grupo n\xe3o tem impedimento"},"descricao":{"codigo":"uniplus.grupo_formulario.campo_com_impedimento","requisitos":["UNI-REQ-0146"],"oQueAconteceu":["Um campo de um grupo repet\xedvel (um item de `subitens` de um grupo em `grupos`) traz `impedimento`. O impedimento \xe9 a resposta que impede a inscri\xe7\xe3o do candidato; o campo de um grupo, como os da composi\xe7\xe3o familiar, responde por um membro de cada ocorr\xeancia (UNI-REQ-0146), e o impedimento de um membro n\xe3o \xe9 o da inscri\xe7\xe3o do candidato.","A recusa vem na lista `errors` da resposta, com `field` igual a `grupos[i].subitens[j].impedimento`, e a mensagem traz o c\xf3digo do fato do campo. Na cria\xe7\xe3o e na atualiza\xe7\xe3o de um modelo de formul\xe1rio o `field` come\xe7a por `conteudo.`. H\xe1 uma entrada por campo de grupo com impedimento, junto das demais recusas da forma do grupo. Nada \xe9 gravado.","Na grava\xe7\xe3o dos itens do formul\xe1rio, a recusa vem junto com as outras recusas da forma dos grupos e dos itens, antes de o cat\xe1logo de fatos ser consultado. Nos modelos, ela s\xf3 \xe9 conferida quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Retire `impedimento` do campo do grupo. Se a resposta de um fato do candidato deve impedir a inscri\xe7\xe3o, declare o impedimento num item do formul\xe1rio de inscri\xe7\xe3o, fora do grupo."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Grupo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);